create table if not exists public.baazi_rooms(code text primary key,state jsonb not null,updated_at timestamptz not null default now());alter table public.baazi_rooms enable row level security;create policy "read" on public.baazi_rooms for select to anon,authenticated using(true);create policy "insert" on public.baazi_rooms for insert to anon,authenticated with check(true);create policy "update" on public.baazi_rooms for update to anon,authenticated using(true) with check(true);alter publication supabase_realtime add table public.baazi_rooms;